import random

def kth_largest(nums: list[int], k: int) -> int:
    """Returns the k-th largest element in an unsorted list using the Quickselect algorithm, 
    which has an average time complexity of O(n) and a worst-case time complexity of O(n^2)."""

    def quickselect(left, right, idx):
        pivot = nums[random.randint(left, right)]
        l, r = left, right

        while l <= r:
            while l <= r and nums[l] > pivot:
                l += 1
            while l <= r and nums[r] < pivot:
                r -= 1
            if l <= r:
                nums[l], nums[r] = nums[r], nums[l]
                l += 1
                r -= 1

        if left + idx <= r:
            return quickselect(left, r, idx)
        if left + idx >= l:
            return quickselect(l, right, idx - (l - left))
        return nums[r + 1]

    return quickselect(0, len(nums) - 1, k - 1)
